command:
/**
 * SVA example: Launched Missile
 * The selected token fires a missile at every target: launch smoke, missile, explosion and a
 * scorched crack on the ground that fades away.
 *
 * Usage: select the launcher, target one or more tokens, run.
 * Requires: Sargas Visual Automation + JB2A (Patreon). No Sequencer needed.
 */
const SVA = game.modules.get("sargas-visual-automation")?.api;
if (!SVA?.ready) return ui.notifications.error("Sargas Visual Automation is not ready.");

const FILES = {
  launchSmoke: "jb2a.smoke.puff.side.02.white",
  missile: "jb2a.throwable.launch.missile.01.blue",
  blast: "jb2a.explosion.08.dark_orange",
  crater: "jb2a.impact.ground_crack.orange"
};

const launcher = canvas.tokens.controlled[0] ?? token;
const targets = [...game.user.targets];
if (!launcher) return ui.notifications.warn("Select the launching token.");
if (!targets.length) return ui.notifications.warn("Target at least one token.");

await SVA.net.preload(Object.values(FILES));
const sleep = (ms) => new Promise((resolve) => setTimeout(resolve, ms));

const runs = [];
for (const target of targets) {
  const seq = SVA.sequence();
  // Back-blast: the smoke points away from the target.
  seq.effect().file(FILES.launchSmoke).atLocation(launcher).rotateTowards(target).rotate(180).scale(0.5);
  seq.effect().file(FILES.missile).atLocation(launcher).stretchTo(target).waitUntilFinished(-150);
  seq.effect().file(FILES.blast).atLocation(target).scaleToObject(2);
  seq
    .effect()
    .file(FILES.crater)
    .atLocation(target)
    .layer("belowTokens")
    .scaleToObject(1.6)
    .scaleIn(0.2, 150, { ease: "easeOutCubic" })
    .duration(4500)
    .fadeOut(3000, { ease: "easeInQuad" });
  runs.push(seq.play());
  await sleep(600 + Math.random() * 400); // salvo feel when several targets are hit
}
await Promise.all(runs);
